BEGIN;
CREATE TABLE public.users (
 id BIGINT PRIMARY KEY,username VARCHAR(100) NOT NULL,display_name VARCHAR(150) NOT NULL,
 is_active BOOLEAN NOT NULL DEFAULT TRUE,
 created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE public.managed_databases (
 id BIGINT PRIMARY KEY,
 connection_options JSONB NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE public.sessions (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id              BIGINT NOT NULL REFERENCES public.users(id),
    authority_version BIGINT NOT NULL CHECK(authority_version>0),
 rotation_version BIGINT NOT NULL DEFAULT 1,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_seen_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    idle_expires_at      TIMESTAMPTZ NOT NULL,
    absolute_expires_at  TIMESTAMPTZ NOT NULL,
    revoked_at           TIMESTAMPTZ
);

CREATE INDEX sessions_user_id_idx ON public.sessions (user_id);

CREATE TABLE public.session_tokens (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id         UUID NOT NULL REFERENCES public.sessions(id),
    token_hash         BYTEA NOT NULL UNIQUE,
    issued_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    replaced_at        TIMESTAMPTZ,
    grace_expires_at   TIMESTAMPTZ
);

CREATE INDEX session_tokens_session_id_idx ON public.session_tokens (session_id);

CREATE UNIQUE INDEX session_tokens_current_per_session_key
    ON public.session_tokens (session_id)
    WHERE replaced_at IS NULL;

CREATE TABLE public.migration_drafts (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    database_id    BIGINT NOT NULL REFERENCES public.managed_databases(id),
    created_by     BIGINT NOT NULL REFERENCES public.users(id),
    title          VARCHAR(255) NOT NULL,
    input_mode     VARCHAR(10) NOT NULL,
    operations     JSONB,
    sql_text       TEXT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT migration_drafts_input_mode_check
        CHECK (input_mode IN ('visual', 'sql')),
    CONSTRAINT migration_drafts_operations_check
        CHECK (operations IS NULL OR jsonb_typeof(operations) = 'array')
);

CREATE INDEX migration_drafts_database_id_idx ON public.migration_drafts (database_id);

CREATE TABLE public.migration_executions (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    database_id         BIGINT NOT NULL REFERENCES public.managed_databases(id),
    draft_id            BIGINT REFERENCES public.migration_drafts(id),
    executed_by         BIGINT NOT NULL REFERENCES public.users(id),
    description         TEXT,
    sql_text            TEXT NOT NULL,
    attempted_version   BIGINT NOT NULL,
    execution_mode      VARCHAR(24) NOT NULL DEFAULT 'transactional',
    completed_statements INTEGER NOT NULL DEFAULT 0,
    total_statements    INTEGER NOT NULL DEFAULT 0,
    applied_version     BIGINT,
    status              VARCHAR(12) NOT NULL,
    error_message       TEXT,
    started_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    finished_at         TIMESTAMPTZ,

    CONSTRAINT migration_executions_status_check
        CHECK (status IN ('running', 'succeeded', 'failed')),
    CONSTRAINT migration_executions_attempted_version_check
        CHECK (attempted_version > 0),
    CONSTRAINT migration_executions_applied_version_check
        CHECK (applied_version IS NULL OR applied_version > 0),
    CONSTRAINT migration_executions_success_version_check
        CHECK (
            (status = 'succeeded' AND applied_version IS NOT NULL)
            OR (status IN ('running', 'failed') AND applied_version IS NULL)
        )
);

CREATE UNIQUE INDEX migration_executions_applied_version_key
    ON public.migration_executions (database_id, applied_version)
    WHERE status = 'succeeded';

CREATE INDEX migration_executions_database_started_at_idx
    ON public.migration_executions (database_id, started_at DESC);
CREATE INDEX migration_executions_draft_id_idx ON public.migration_executions (draft_id);


CREATE FUNCTION public.migration_content_hash(up_sql text,down_sql text,irreversible boolean,reason text)
 RETURNS text LANGUAGE SQL IMMUTABLE STRICT AS $$
 SELECT encode(sha256(convert_to(octet_length(up_sql)::text||':'||up_sql||
 octet_length(down_sql)::text||':'||down_sql||irreversible::text||':'||reason,'UTF8')),'hex')
$$;
CREATE TABLE public.migration_definitions (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 database_id BIGINT NOT NULL REFERENCES public.managed_databases(id),
 title TEXT NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 255),
 logical_version BIGINT CHECK(logical_version>0),
 created_by BIGINT NOT NULL REFERENCES public.users(id),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE public.migration_revisions (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 definition_id BIGINT NOT NULL REFERENCES public.migration_definitions(id),
 revision_no BIGINT NOT NULL CHECK(revision_no>0),
 up_sql TEXT NOT NULL CHECK(length(btrim(up_sql))>0),
 down_sql TEXT NOT NULL DEFAULT '',
 irreversible BOOLEAN NOT NULL DEFAULT FALSE,
 irreversible_reason TEXT NOT NULL DEFAULT '',
 sql_hash TEXT NOT NULL CHECK(sql_hash=public.migration_content_hash(up_sql,down_sql,irreversible,irreversible_reason)),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(), frozen_at TIMESTAMPTZ,
 CHECK((irreversible AND down_sql='' AND length(btrim(irreversible_reason))>=10)
 OR (NOT irreversible AND length(btrim(down_sql))>0 AND irreversible_reason='')),
 UNIQUE(definition_id,revision_no)
);
CREATE TABLE public.migration_database_state (
 database_id BIGINT PRIMARY KEY REFERENCES public.managed_databases(id),
 active_version BIGINT NOT NULL DEFAULT 0 CHECK(active_version>=0),
 generation BIGINT NOT NULL DEFAULT 0 CHECK(generation>=0),
 active_stack UUID[] NOT NULL DEFAULT '{}', forward_stack UUID[] NOT NULL DEFAULT '{}',
 blocked_reason TEXT NOT NULL DEFAULT '', updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 CHECK(active_version=cardinality(active_stack))
);
CREATE TABLE public.migration_reviews (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 revision_id BIGINT NOT NULL REFERENCES public.migration_revisions(id),
 database_id BIGINT NOT NULL REFERENCES public.managed_databases(id),
 action TEXT NOT NULL CHECK(action IN('up','rollback','forward','batch_cancel')),
 target_execution_id UUID, target_job_id UUID,
 review_state TEXT NOT NULL DEFAULT 'pending_review' CHECK(review_state IN('pending_review','approved','rejected','invalidated')),
 authority_revision BIGINT NOT NULL CHECK(authority_revision>0),
 authority_snapshot JSONB NOT NULL,
 connection_fingerprint TEXT NOT NULL,
 expected_generation BIGINT NOT NULL CHECK(expected_generation>=0),
 expected_active_version BIGINT NOT NULL CHECK(expected_active_version>=0),
 recovery_fingerprint TEXT NOT NULL DEFAULT '',
 action_hash TEXT NOT NULL,
 submitted_by BIGINT NOT NULL REFERENCES public.users(id), submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 queued_job_id UUID UNIQUE, idempotency_key TEXT,
 CHECK((action IN('rollback','forward'))=(target_execution_id IS NOT NULL)),
 CHECK((action='batch_cancel')=(target_job_id IS NOT NULL)),
 CHECK((queued_job_id IS NULL)=(idempotency_key IS NULL))
);
CREATE UNIQUE INDEX migration_review_live_action ON public.migration_reviews(revision_id,action,
 COALESCE(target_execution_id,'00000000-0000-0000-0000-000000000000'::uuid),
 COALESCE(target_job_id,'00000000-0000-0000-0000-000000000000'::uuid))
 WHERE review_state IN('pending_review','approved');
CREATE TABLE public.migration_review_required_groups (
 review_id BIGINT NOT NULL REFERENCES public.migration_reviews(id),
 group_id BIGINT NOT NULL, leader_user_id_snapshot BIGINT NOT NULL,
 access_level TEXT NOT NULL CHECK(access_level IN('view_only','view_edit')),
 required_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(review_id,group_id)
);
CREATE TABLE public.migration_approvals (
 review_id BIGINT NOT NULL, group_id BIGINT NOT NULL,
 approver_user_id BIGINT NOT NULL REFERENCES public.users(id),
 decision TEXT NOT NULL CHECK(decision IN('approve','reject')),
 decided_at TIMESTAMPTZ NOT NULL DEFAULT now(), note TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(review_id,group_id),
 FOREIGN KEY(review_id,group_id) REFERENCES public.migration_review_required_groups(review_id,group_id)
);
-- Queue storage contract owned here; claiming/execution/retry policy belongs to P3.
CREATE TABLE public.migration_jobs (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
 review_id BIGINT NOT NULL UNIQUE REFERENCES public.migration_reviews(id),
 database_id BIGINT NOT NULL REFERENCES public.managed_databases(id),
 operation TEXT NOT NULL CHECK(operation IN('up','rollback','forward','batch_cancel')),
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','succeeded','failed','partial','uncertain','reverting','reverted','partially_reverted')),
 requested_by BIGINT NOT NULL REFERENCES public.users(id),
 idempotency_key TEXT NOT NULL CHECK(length(idempotency_key) BETWEEN 1 AND 200),
 lease_owner TEXT, lease_until TIMESTAMPTZ,
 execution_id UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE,
 attempt INTEGER NOT NULL DEFAULT 0 CHECK(attempt>=0),
 max_attempts INTEGER NOT NULL DEFAULT 5 CHECK(max_attempts BETWEEN 1 AND 20),
 action_hash TEXT NOT NULL DEFAULT '', sql_hash TEXT NOT NULL DEFAULT '',
 error_class TEXT NOT NULL DEFAULT '', cancellation_job_id UUID,
 next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 trace_context JSONB NOT NULL DEFAULT '{}'::jsonb,
 UNIQUE(requested_by,idempotency_key), UNIQUE(id,review_id)
);
ALTER TABLE public.migration_reviews ADD CONSTRAINT migration_review_queued_job
 FOREIGN KEY(queued_job_id,id) REFERENCES public.migration_jobs(id,review_id);
CREATE INDEX migration_jobs_ready ON public.migration_jobs(next_attempt_at,created_at) WHERE status='pending';
CREATE INDEX migration_jobs_database_order ON public.migration_jobs(database_id,created_at,id);
CREATE TABLE public.migration_job_attempts (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 job_id UUID NOT NULL REFERENCES public.migration_jobs(id), attempt_no INTEGER NOT NULL CHECK(attempt_no>0),
 started_at TIMESTAMPTZ NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ,
 error_class TEXT NOT NULL DEFAULT '', error_message TEXT NOT NULL DEFAULT '',
 outcome TEXT NOT NULL DEFAULT 'running' CHECK(outcome IN('running','succeeded','failed','uncertain','partial')),
 UNIQUE(job_id,attempt_no)
);
CREATE TABLE public.migration_batch_progress (
 job_id UUID PRIMARY KEY REFERENCES public.migration_jobs(id),
 committed_batches BIGINT NOT NULL DEFAULT 0 CHECK(committed_batches>=0),
 committed_rows BIGINT NOT NULL DEFAULT 0 CHECK(committed_rows>=0),
 reverted_batches BIGINT NOT NULL DEFAULT 0 CHECK(reverted_batches>=0),
 reverted_rows BIGINT NOT NULL DEFAULT 0 CHECK(reverted_rows>=0),
 last_cursor TEXT NOT NULL DEFAULT '', total_rows_estimate BIGINT CHECK(total_rows_estimate>=0),
 partial_state TEXT NOT NULL DEFAULT '', updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE public.migration_execution_history (
 history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 execution_id UUID NOT NULL UNIQUE, job_id UUID NOT NULL UNIQUE,
 review_id BIGINT UNIQUE REFERENCES public.migration_reviews(id),
 definition_id BIGINT NOT NULL REFERENCES public.migration_definitions(id),
 revision_id BIGINT NOT NULL REFERENCES public.migration_revisions(id),
 database_id BIGINT NOT NULL REFERENCES public.managed_databases(id),
 logical_version BIGINT NOT NULL CHECK(logical_version>0),
 actor_id BIGINT NOT NULL REFERENCES public.users(id),
 operation TEXT NOT NULL CHECK(operation IN('up','rollback','forward','batch_cancel')),
 sql_snapshot TEXT NOT NULL, committed_at TIMESTAMPTZ NOT NULL,
 reverses_execution_id UUID REFERENCES public.migration_execution_history(execution_id),
 target_execution_id UUID REFERENCES public.migration_execution_history(execution_id),
 target_receipt TEXT NOT NULL CHECK(length(target_receipt)>0),
 CHECK((operation='rollback')=(reverses_execution_id IS NOT NULL))
);
ALTER TABLE public.migration_reviews ADD CONSTRAINT migration_reviews_target_execution
 FOREIGN KEY(target_execution_id) REFERENCES public.migration_execution_history(execution_id);
CREATE UNIQUE INDEX migration_exact_reversal ON public.migration_execution_history(reverses_execution_id)
 WHERE reverses_execution_id IS NOT NULL;
CREATE INDEX migration_history_database_order ON public.migration_execution_history(database_id,history_seq DESC);
CREATE FUNCTION public.protect_migration_revision() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.frozen_at IS NOT NULL THEN RAISE EXCEPTION 'submitted revisions are immutable' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF ROW(OLD.definition_id,OLD.revision_no,OLD.up_sql,OLD.down_sql,OLD.irreversible,OLD.irreversible_reason,OLD.sql_hash,OLD.created_at)
 IS DISTINCT FROM ROW(NEW.definition_id,NEW.revision_no,NEW.up_sql,NEW.down_sql,NEW.irreversible,NEW.irreversible_reason,NEW.sql_hash,NEW.created_at)
 OR (OLD.frozen_at IS NOT NULL AND NEW.frozen_at IS DISTINCT FROM OLD.frozen_at) THEN
  RAISE EXCEPTION 'revisions are immutable; create a new revision' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER immutable_migration_revision BEFORE UPDATE OR DELETE ON public.migration_revisions
 FOR EACH ROW EXECUTE FUNCTION public.protect_migration_revision();
CREATE FUNCTION public.protect_migration_history() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'committed history is append-only' USING ERRCODE='23514'; END $$;
CREATE TRIGGER append_only_migration_history BEFORE UPDATE OR DELETE ON public.migration_execution_history
 FOR EACH ROW EXECUTE FUNCTION public.protect_migration_history();

COMMIT;
